306	    for ch in text.chars() {
307	        if ch == '`' {
308	            if in_code {
309	                code_ranges.push(code_start..stripped.len());
310	            } else {
311	                code_start = stripped.len();
312	            }
313	            in_code = !in_code;
314	        } else {
315	            stripped.push(ch);
316	        }
317	    }
318	
319	    if code_ranges.is_empty() {
320	        return None;
321	    }
322	
323	    Some((SharedString::from(stripped), code_ranges))
